<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{adminApi}from'../api';import{ApiError,type WmNews}from'@leadnews/shared';import{ElMessage,ElMessageBox}from'element-plus';const route=useRoute(),router=useRouter(),news=ref<WmNews>(),busy=ref(false),reason=ref('');const id=Number(route.params.id);async function approve(){await ElMessageBox.confirm('确认通过该稿件？通过后将进入发布链路。','二次确认');busy.value=true;try{const x=await adminApi.approve(id);ElMessage.success(`审核通过，发布状态：${x.publishStatus}`);router.push('/audit')}catch(e){ElMessage.error(e instanceof ApiError?e.message:'操作失败')}finally{busy.value=false}}async function reject(){if(!reason.value.trim())return void ElMessage.warning('请填写拒绝原因');await ElMessageBox.confirm('确认拒绝该稿件？','二次确认');busy.value=true;try{await adminApi.reject(id,reason.value.trim());ElMessage.success('已拒绝');router.push('/audit')}catch(e){ElMessage.error(e instanceof ApiError?e.message:'操作失败')}finally{busy.value=false}}onMounted(async()=>news.value=await adminApi.detail(id))</script><template><div v-if="news" class="stack"><section class="panel"><p class="meta">{{news.authorName}} · {{news.submittedTime}}</p><h1>{{news.title}}</h1><el-alert v-if="news.reason" :title="news.reason" type="warning" show-icon/><template v-for="(b,i) in news.content" :key="i"><p v-if="b.type==='text'" class="content-block">{{b.value}}</p><img v-else :src="b.value" class="content-image" alt="稿件图片"></template></section><section class="panel"><h2>审核轨迹</h2><div class="timeline"><div v-for="a in news.auditTrail" :key="`${a.auditVersion}-${a.createdTime}`" class="timeline-item"><strong>{{a.auditStage}} → {{a.decision}}</strong><p>{{a.reason}}</p><p class="meta">风险 {{a.riskLevel||'-'}} · 标签 {{a.riskTags?.join(' / ')||'-'}} · 置信度 {{a.confidence??'-'}} · {{a.createdTime}}</p></div></div></section><section class="panel"><h2>人工决策</h2><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="拒绝时必须填写原因"/><div class="toolbar" style="margin-top:14px"><el-button type="success" :loading="busy" @click="approve">通过</el-button><el-button type="danger" :loading="busy" @click="reject">拒绝</el-button></div></section></div><div v-else class="empty">正在读取审核详情…</div></template>
